result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/molar_mass.py", "content": """"Molar mass calculator with a recursive-descent formula parser.

Grammar (EBNF-ish):
    formula  := hydrate
    hydrate  := part ('.' integer? part)*        # dot-hydrate notation, e.g. CuSO4.5H2O
    part     := group+                           # a sequence of groups, each optionally multiplied by an integer
    group    := element | '(' formula ')'
    element  := UPPER (LOWER LOWER?)?
"""

from __future__ import annotations

ATOMIC_WEIGHTS = {
    "H": 1.008,
    "C": 12.011,
    "N": 14.007,
    "O": 15.999,
    "Na": 22.990,
    "Mg": 24.305,
    "Al": 26.982,
    "P": 30.974,
    "S": 32.06,
    "Cl": 35.45,
    "K": 39.098,
    "Ca": 40.078,
    "Fe": 55.845,
    "Cu": 63.546,
}


class FormulaError(ValueError):
    """Raised for any invalid chemical formula."""


def _is_digit(ch: str) -> bool:
    return ch.isdigit()


class _Parser:
    def __init__(self, text: str) -> None:
        self.text = text.strip()
        self.pos = 0

    def error(self, message: str) -> FormulaError:
        return FormulaError(f"{message} at position {self.pos + 1} in {self.text!r}")

    def peek(self) -> str | None:
        if self.pos < len(self.text):
            return self.text[self.pos]
        return None

    def parse_integer(self) -> int | None:
        start = self.pos
        while self.peek() is not None and _is_digit(self.peek()):
            self.pos += 1
        if self.pos == start:
            return None
        return int(self.text[start : self.pos])

    def parse_formula(self) -> float:  # total mass of the remaining input
        total = self.parse_hydrate()
        if self.peek() is not None:
            raise self.error(f"unexpected character {self.peek()!r}")
        return total

    def parse_hydrate(self) -> float:
        """formula := part ('.' integer? part)*"""
        total = self.parse_part()
        while self.peek() == ".":
            self.pos += 1
            multiplier = self.parse_integer()
            if multiplier is None:
                multiplier = 1
            total += multiplier * self.parse_part()
        return total

    def parse_part(self) -> float:
        """part := group+"""
        if self.peek() is None:
            raise self.error("expected element symbol or '('")
        total = 0.0
        while True:
            ch = self.peek()
            if ch is not None and (ch.isupper() or ch == "("):
                total += self.parse_group()
            else:
                break
        if total == 0.0:
            raise self.error("expected element symbol or '('")
        return total

    def parse_group(self) -> float:
        """group := element | '(' formula ')'"""
        ch = self.peek()
        if ch == "(":
            self.pos += 1
            mass = self.parse_hydrate()
            if self.peek() != ")":
                raise self.error("unbalanced parenthesis: expected ')'")
            self.pos += 1  # consume ')'
        else:
            mass = self.parse_element()
        count = self.parse_integer()
        return mass * (count if count is not None else 1)

    def parse_element(self) -> float:
        """element := UPPER (LOWER)?"""
        ch = self.peek()
        if ch is None or not ch.isupper():
            raise self.error(f"expected element symbol, got {ch!r}")
        start = self.pos
        self.pos += 1
        nxt = self.peek()
        if nxt is not None and nxt.islower():
            symbol = self.text[start : self.pos + 1]
            self.pos += 1
        else:
            symbol = ch
        weight = ATOMIC_WEIGHTS.get(symbol)
        if weight is None:
            self.pos = start + len(symbol)
            raise self.error(f"unknown element symbol {symbol!r}")
        return weight


def molar_mass(formula: str) -> float:
    """Return the molar mass (g/mol) of the chemical formula.

    Supports nested parentheses and dot-hydrate notation, e.g.
    molar_mass('CuSO4.5H2O') -> 249.677

    Raises FormulaError for unknown elements, unbalanced parentheses,
    empty formulas, or other malformed input.
    """
    if not isinstance(formula, str):
        raise FormulaError("formula must be a string")
    parser = _Parser(formula)
    if not parser.text:
        raise FormulaError("empty formula")
    return round(parser.parse_formula(), 6)
